export function Snackbar({
  message = "{{message}}",
  actionLabel = "{{actionLabel}}",
  showAction = {{showAction}},
  duration = {{duration}},
}) {
  return (
    <div role="status" aria-live="polite" style={{ position: "relative", display: "flex", alignItems: "center", gap: 16,
      maxWidth: 380, minWidth: 260, padding: "12px 16px", boxSizing: "border-box", borderRadius: 10, background: "#241430",
      color: "#FAF7F2", font: "13.5px/1.4 system-ui, sans-serif", overflow: "hidden", boxShadow: "0 10px 28px rgba(36,20,48,.25)" }}>
      <p style={{ flex: 1, margin: 0 }}>{message}</p>
      {showAction && (
        <button type="button" style={{ border: "none", background: "transparent", color: "#A8E6C1", fontWeight: 700,
          fontSize: 12.5, cursor: "pointer", padding: "4px 6px", borderRadius: 4, whiteSpace: "nowrap" }}>{actionLabel}</button>
      )}
      <span aria-hidden="true" style={{ position: "absolute", left: 0, bottom: 0, height: 3, width: "100%", background: "#A8E6C1",
        transformOrigin: "left", animation: `snackbar-react-shrink ${duration}s linear forwards` }} />
      <style>{`@keyframes snackbar-react-shrink { from { transform: scaleX(1); } to { transform: scaleX(0); } }`}</style>
    </div>
  );
}
